class Matrix {
public:
    Matrix(int rows, int columns) : rows_(rows), columns_(columns) {
        data_ = new double[rows * columns];
    }

    void setValue(int row, int column, double value) {
        data_[row * columns + column] = value;
    }

    double getValue(int row, int column) const {
        return data_[row * columns + column];
    }

private:
    int rows_;
    int columns_;
    double* data_;
};

class BitmapMatrix : public QMatrix {
public:
    BitmapMatrix(int rows, int columns) : QMatrix(rows, columns) {}

    QPixmap toPixmap() const {
        QPixmap pixmap(width(), height());
        QPainter painter(&pixmap);
        painter.setPen(Qt::NoPen);
        painter.setBrush(Qt::black);
