gaussian_filtered_image = fspecial('gaussian', [3 3], 0.5); % 3x3 kernel, standard deviation of 0.5
gray_image = gray_image .* double(gaussian_filtered_image);

% Define Sobel operator in x direction
sobel_x = [-1 0 1; -2 0 2; -1 0 1];

% Define Sobel operator in y direction
