// src/mongodb.config.ts
import { ConfigService } from '@nestjs/config';
import { MongoClientOptions, MongoClient } from 'mongodb';

export const mongoConfig = (configService: ConfigService) => {
  const url = configService.get('MONGODB_URL');
  const databaseName = configService.get('MONGODB_DATABASE_NAME');

  return {
    uri: url,
    databaseName,
  } as MongoClientOptions;
};
```

3. Create a `mongodb.service.ts` file in your `src` folder to handle the MongoDB connection and model creation:

```typescript
// src/mongodb.service.ts
import { Injectable } from '@nestjs/common';
import { MongoClient } from 'mongodb';
import { Model } from 'mongoose';

@Injectable()
export class MongoDbService {
  private client: MongoClient;

  constructor(private configService: ConfigService) {}

  async connect() {
    this.client = new MongoClient(await mongoConfig(this.configService));
    await this.client.connect();
  }

  async close() {
    await this.client.close();
  }

  getModel(modelName: string): Model {
    return this.client.db(this.configService.get('MONGODB_DATABASE_NAME')).model(modelName);
  }
}
