using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first, second, numElements;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> first >> second)) {
        throw runtime_error("Invalid input. Please enter two integers.");
    }

    if (first < 0 || second < 0) {
        throw runtime_error("Both integers must be non-negative.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        throw runtime_error("The number of sequence elements must be positive.");
    }

    vector<int> sequence(numElements);
    sequence[0] = first;
    sequence[1] = second;

    for (int i = 2; i < numElements; i++) {
        sequence[i] = fibonacci(i, first, second);
    }

    cout << "Fibonacci sequence:";
    for (int i = 0; i < numElements; i++) {
        cout << " " << sequence[i];
    }
    cout << endl;

    return 0;
}
```

