        return True
    else:
        return False

def extract_photo_links(album_link):
    response = requests.get(album_link)
    soup = BeautifulSoup(response.text, 'html.parser')
    photo_links = []
    for link in soup.find_all('a'):
        if link.get('href').startswith('https://photos.google.com/'):
            photo_links.append(link.get('href'))
    return photo_links

def main():
    album_link = "https://photos.google.com/share?id=YOUR_ALBUM_ID"
    photo_links = extract_photo_links(album_link)
    for link in photo_links:
        if download_photo(link):
            print(f"Downloaded {link}")
        else:
            print(f"Failed to download {link}")

if __name__ == "__main__":
    main()
```

Replace `YOUR_ALBUM_ID` with your actual album ID. This program will download all the photos from the specified album link and save them as JPEG files in the current directory.

