Here's a MATLAB code that identifies the tense used in a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Check for present tense
    if strcmpi(words{end}, 'ing') || strcmpi(words{end}, 's')
        tense = 'present';
    elseif strcmpi(words{end}, 'ed')
        tense = 'past';
    elseif strcmpi(words{end}, 'been')
        tense = 'perfect';
    elseif strcmpi(words{end}, 'going')
        tense = 'future';
    else
        tense = 'other';
    end
end

% Test the function with the given sentence
