Here's a React component using the `useState` hook to convert temperatures between Fahrenheit and Celsius:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('Fahrenheit');

  const handleConvert = () => {
    if (unit === 'Fahrenheit') {
      setTemperature((temperature * 9 / 5) + 32);
      setUnit('Celsius');
    } else {
      setTemperature((temperature - 32) * 5 / 9);
      setUnit('Fahrenheit');
    }
  };

  return (
    <div>
      <input type="number" value={temperature} onChange={e => setTemperature(parseFloat(e.target.value))} />
      <select value={unit} onChange={e => setUnit(e.target.value)}>
        <option value="Fahrenheit">Fahrenheit</option>
        <option value="Celsius">Celsius</option>
      </select>
      <button onClick={handleConvert}>Convert</button>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

