```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"
)

type StructInfo struct {
	Name     string
	Fields   []FieldInfo
}

type FieldInfo struct {
	Name       string
	Type       string
	Optional bool
}

func parseStruct(file string) (StructInfo, error) {
	data, err := ioutil.ReadFile(file)
	if err != nil {
		return StructInfo{}, err
	}

	re := regexp.MustCompile(`struct\s+(\w+)\s*{`)
	matches := re.FindStringSubmatch(string(data))
	if len(matches) != 2 {
		return StructInfo{}, fmt.Errorf("invalid struct definition")
	}

	name := matches[1]
	fields := []FieldInfo{}

	re = regexp.MustCompile(`(\w+)\s+(\w+)\s*(?:\[\d+\])?\s*(?:\*)?`)
	for _, match := range re.FindAllStringSubmatch(string(data), -1) {
		fieldName := match[1]
		fieldType := match[2]
		optional := false

		if match[3] == "[" && match[3] == "]" {
			fieldType += "[]"
		}

		if match[4] == "*" {
			optional = true
		}

		fields = append(fields, FieldInfo{Name: fieldName, Type: fieldType, Optional: optional})
	}

	return StructInfo{Name: name, Fields: fields}, nil
}

