        disp(['Name: ' num2str(patients(i).name)]);
        disp(['Age: ' num2str(patients(i).age)]);
        disp(['Diagnosis: ' num2str(patients(i).diagnosis)]);
        disp(['Treatment: ' num2str(patients(i).treatment)]);
    end
end

% Create function to update patient data
function update_patient(patient_index, new_data)
    % Check if patient index is valid
    if ~ismember(patient_index, 1:numel(patients))
        error('Invalid patient index.');
    end

    % Update patient data
    patients(patient_index) = new_data;
end

Here's a simple decorator for your use case:

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IsProduction = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.env === 'production';
  },
);

export function ProductionsMiddleware(
  isProduction: boolean,
): (ctx: ExecutionContext, next: () => void) => void {
  return (ctx: ExecutionContext, next: () => void) => {
    if (isProduction) {
      next();
    } else {
      ctx.res.status(405).send('Not allowed in non-production environment.');
    }
  };
}
```

Now you can use this decorator on your controller actions like this:

```typescript
import { Controller, Get, UseInterceptors } from '@nestjs/common';
import { IsProduction } from './is-production.decorator';
import { ProductionsMiddleware } from './productions.middleware';

@Controller()
export class MyController {
  @Get()
  @UseInterceptors(ProductionsMiddleware(IsProduction))
  public get(): any {
    // Your logic here
  }
}
```

