To create a simple toast notification using React Context, follow these steps:

1. Create a ToastContext.js file:
```javascript
import React from 'react';

const ToastContext = React.createContext({
  showToast: () => {},
});

export default ToastContext;
```

2. Create a ToastProvider.js file:
```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

function ToastProvider({ children }) {
  const [showToast, setShowToast] = React.useState(false);

  function handleClick() {
    setShowToast(true);
  }

  return (
    <ToastContext.Provider value={{ showToast, handleClick }}>
      {children}
    </ToastContext.Provider>
  );
}

export default ToastProvider;
```

3. Create a Toast.js file:
```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { showToast, handleClick } = React.useContext(ToastContext);

  if (!showToast) {
    return null;
  }

  return (
    <div className="toast">
      <p>This is a toast notification!</p>
      <button onClick={handleClick}>Close</button>
    </div>
  );
}

export default Toast;
```

4. Use the ToastProvider and Toast components in your app:
```javascript
import React from 'react';
import ToastProvider from './ToastProvider';
import Toast from './Toast';

function App() {
  return (
    <ToastProvider>
      <button onClick={() => alert('Hello!')}>Click me</button>
      <Toast />
    </ToastProvider>
  );
}

export default App;
```

Now you have a simple toast notification using React Context. You can customize the toast style and behavior as needed.

