```python
def parse_scientific_notation(input_str):
    match = re.match(r'(\d+)\.?(\d*)e(\d+)', input_str)
    if match:
        integer, fraction, exponent = match.groups()
        num = float(integer) * (10 ** int(exponent))
        if fraction is not None:
            num += float(fraction) / (10 ** int(exponent))
        return num
    else:
        raise ValueError("Invalid scientific notation input")
```

