```javascript
const { promisify } = require('util');
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.redis = new Redis({
      host: 'localhost',
      port: 6379,
      family: 4,
      tls: {
        cert: '/path/to/cert.pem',
        key: '/path/to/key.pem',
      },
    });

    this.redis.on('error', (err) => {
      console.error('Error with Redis:', err);
    });
  }

  async isAlive() {
    try {
      await this.redis.ping();
      return true;
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    const result = await promisify(this.redis.get)(key);
    return result;
  }

  async set(key, value, duration) {
    await promisify(this.redis.setex)(key, duration, value);
  }

  async del(key) {
    await promisify(this.redis.del)(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

