Here's a PowerShell script that recursively checks folders for SIDs in SIDHistory:

```powershell
# Define function to check if a SID exists in SIDHistory
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $ldapFilter = "(&(objectClass=user)(sAMAccountName=$sid)(memberOf:1.2.840.113556.1.4.1941:=$domain)))"
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = $ldapFilter
    $results = $searcher.FindAll()
    return ($results.Count -gt 0)
}

# Define function to recursively check folder ACLs
function CheckFolderACLs($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = $access.IdentityReference
                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "Folder: $($folderPath)"
                    Write-Host "  SID: $sid"
                    Write-Host "  SIDHistory: True"
                }
            }
        }
        CheckFolderACLs($_.FullName)
    }
}

# Example usage
$folderPath = "C:\Test"
CheckFolderACLs($folderPath)
```

Replace `C:\Test` with the root folder you want to start checking from. This script will recursively check all folders and subfolders within the specified path, and output any folders where the ACLs reference SIDs that exist in SIDHistory.
